export default class Buttons {
	static pluginName = 'buttons';

	/**
	 * @constructor
	 * @param {Object} ctx - the carousel context that the buttons will control
	 */
	constructor(ctx) {
		const _ = this;
		_.ctx = ctx;
		_.navOptions = {};
		_.prevButton = null;
		_.nextButton = null;
		_.smartButtonImages = [];
		_.smartButtonsRaf = 0;
		_.initTimers = [];
		_.viewportObserver = null;

		// define all event handlers in one object
		_.handlers = {
			// handler for prev button click
			previousClick: (e) => {
				// trigger user interacted event
				_.ctx.emitter.emit(_.ctx.events.user.interacted, { via: 'button', event: e });
				_.ctx.commands.previous(5);
			},

			// handler for next button click
			nextClick: (e) => {
				// trigger user interacted event
				_.ctx.emitter.emit(_.ctx.events.user.interacted, { via: 'button', event: e });
				_.ctx.commands.next(-5);
			},

			// handler for button focus
			buttonFocus: (e) => {
				// pause autoplay on focus if enabled
				_.ctx.emitter.emit(_.ctx.events.user.interacted, { via: 'focus', event: e });
			},

			// handler for options changed event
			optionsChanged: () => {
				_.reInit();
			},

			// debounced check for multiple events
			debouncedCheckDisabledState: _.ctx.utils.debounce(() => {
				_.checkDisabledState();
			}, 4),

			// debounce resize so we only measure after a resize burst settles;
			// fast drags otherwise fire many measurements against a still-reflowing layout.
			windowResize: _.ctx.utils.debounce(() => {
				_.#scheduleSmartButtonsUpdate();
			}, 60),

			// the leading slide changed, so the tallest image on screen may have too
			indexChanged: () => {
				_.#scheduleSmartButtonsUpdate();
			},

			imageLoad: () => {
				_.#scheduleSmartButtonsUpdate();
			},
		};

		_.init();
	}

	/**
	 * initialize the navigation buttons
	 */
	init() {
		const _ = this;
		_.navOptions = _.ctx.store.getOptions().navigation || {};

		// pull buttons from DOM, and build the ones the page didn't supply.
		// next before prev: buildButton prepends, so this leaves prev first.
		_.queryDOM();
		if (!_.nextButton) _.nextButton = _.buildButton('next');
		if (!_.prevButton) _.prevButton = _.buildButton('prev');

		// bind events and set up UI
		_.checkButtonOptions();
		_.bindEvents();
		_.checkDisabledState();

		// staggered retries — images/layout may not be measurable yet at init time.
		// only booked when smart positioning is on (it is off by default): with it
		// off updateSmartButtons has nothing to do but clear classes it never set.
		// track the timer ids so destroy() can cancel them if the carousel is
		// removed before they fire (e.g. cart content swaps)
		if (_.navOptions.smartButtons) {
			for (const delay of [8, 30]) {
				_.initTimers.push(setTimeout(() => _.updateSmartButtons(), delay));
			}
		}
	}

	/**
	 * reinitialize on carousel option changes
	 */
	reInit() {
		const _ = this;
		_.navOptions = _.ctx.store.getOptions().navigation || {};
		_.checkButtonOptions();
		_.checkDisabledState();
		_.#syncViewportObserver();
		_.#scheduleSmartButtonsUpdate();
	}

	// every emitter subscription, listed once. bindEvents and destroy both walk
	// this, so a new subscription cannot be added without its matching teardown.
	#subscriptions() {
		const _ = this;
		const events = _.ctx.events;
		const handlers = _.handlers;

		return [
			[events.store.optionsChanged, handlers.optionsChanged],
			[events.store.pageIndexChanged, handlers.debouncedCheckDisabledState],
			[events.store.pageCountChanged, handlers.debouncedCheckDisabledState],
			[events.store.slidesChanged, handlers.debouncedCheckDisabledState],
			[events.store.canLoopChanged, handlers.debouncedCheckDisabledState],
			[events.store.renderIndexChanged, handlers.indexChanged],
			[events.window.resize, handlers.windowResize],
		];
	}

	// the same list for DOM listeners. the capture flag matters on click.
	#buttonListeners() {
		const _ = this;
		return [
			[_.prevButton, 'click', _.handlers.previousClick, true],
			[_.prevButton, 'focus', _.handlers.buttonFocus, false],
			[_.nextButton, 'click', _.handlers.nextClick, true],
			[_.nextButton, 'focus', _.handlers.buttonFocus, false],
		];
	}

	/**
	 * bind all events (DOM and emitter)
	 */
	bindEvents() {
		const _ = this;

		for (const [button, type, handler, capture] of _.#buttonListeners()) {
			button?.addEventListener(type, handler, capture);
		}
		for (const [event, handler] of _.#subscriptions()) {
			_.ctx.emitter.on(event, handler);
		}

		_.#syncViewportObserver();
	}

	/**
	 * check button options and show/hide buttons accordingly
	 */
	checkButtonOptions() {
		const _ = this;
		const nav = _.navOptions;

		// showButtons gates both; each button can still be switched off on its own
		_.#toggleButton(
			_.prevButton,
			nav.showButtons && nav.showPreviousButton !== false,
			'tarot-previous'
		);
		_.#toggleButton(_.nextButton, nav.showButtons && nav.showNextButton !== false, 'tarot-next');
	}

	// show or hide one button. the state classes are only ever added, never
	// removed — a hidden button keeps them so it comes back styled.
	#toggleButton(button, show, className) {
		if (!button) return;
		button.style.display = show ? '' : 'none';
		if (show) button.classList.add('tarot-button', className);
	}

	/**
	 * query buttons from the dom
	 */
	queryDOM() {
		const _ = this;
		const nav = _.navOptions;

		_.prevButton = _.#findButton(nav.previousButtonSelector, 'data-action-tarot-previous');
		_.nextButton = _.#findButton(nav.nextButtonSelector, 'data-action-tarot-next');
	}

	// resolve one button: an author-supplied selector wins, otherwise the first
	// matching descendant whose nearest carousel is this one (so a nested
	// carousel's buttons never get claimed by its parent).
	#findButton(selector, attribute) {
		const _ = this;

		if (selector) {
			const supplied = document.querySelector(selector);
			if (supplied) return supplied;
		}

		return (
			Array.from(_.ctx.carousel.querySelectorAll(`[${attribute}]`)).find(
				(button) => button.closest('tarot-carousel') === _.ctx.carousel
			) || null
		);
	}

	/**
	 * build a navigation button if it doesn't exist
	 * @param {string} type - 'prev' or 'next'
	 * @returns {Element} the created button element
	 */
	buildButton(type) {
		const isNext = type === 'next';
		const dataAttr = isNext ? 'data-action-tarot-next' : 'data-action-tarot-previous';
		const ariaLabel = isNext ? 'next slide' : 'previous slide';
		const svgTitle = isNext ? 'angle right' : 'angle left';
		const svgPath = isNext ? 'm11 25 9-9-9-9' : 'm21 7-9 9 9 9';

		const html = `<button class="tarot-button" ${dataAttr} aria-label="${ariaLabel}"><svg fill="none" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32"><title>${svgTitle}</title><path d="${svgPath}" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg></button>`;
		this.ctx.carousel.insertAdjacentHTML('afterbegin', html);
		return this.ctx.carousel.querySelector(`[${dataAttr}]`);
	}

	// the slides sitting on the current page. renderIndex is the leading slide,
	// derived from the real track position by TrackAnimator, so this stays
	// correct mid-drag — and it avoids restating the pageIndex * slidesPerMove
	// convention that layout-metrics and goToPage already own.
	#slidesOnCurrentPage() {
		const _ = this;
		const slides = _.ctx.store.getSlides();
		if (!slides.length) return [];

		// options-manager resolves slidesPerView to a number >= 1, but it can
		// still be fractional, hence the ceil
		const options = _.ctx.store.getOptions();
		const perView = Math.ceil(options.slidesPerView);
		const renderIndex = _.ctx.store.getState().renderIndex;

		// the last page of a non-looping carousel is clamped by the track, so it
		// shows the final perView slides rather than starting at renderIndex
		const start = options.loop
			? renderIndex
			: Math.min(renderIndex, Math.max(0, slides.length - perView));

		const page = [];
		for (let i = 0; i < perView; i++) {
			const index = options.loop ? (start + i) % slides.length : start + i;
			if (index >= slides.length) break;
			page.push(slides[index]);
		}
		return page;
	}

	// measure the tallest image on the page and re-arm the load listeners in the
	// same pass. a lazy-loaded image measures 0 until it decodes, which would
	// park the buttons at the viewport's midpoint with nothing left to correct
	// them, so anything still loading gets watched.
	#measurePageImages(pageSlides) {
		const _ = this;
		_.#releasePageImages();

		let tallest = 0;
		for (const slide of pageSlides) {
			const image = slide?.querySelector('img');
			if (!image) continue;
			tallest = Math.max(tallest, image.offsetHeight);
			if (image.complete) continue;
			image.addEventListener('load', _.handlers.imageLoad, { once: true });
			_.smartButtonImages.push(image);
		}
		return tallest;
	}

	#releasePageImages() {
		const _ = this;
		for (const image of _.smartButtonImages) {
			image.removeEventListener('load', _.handlers.imageLoad);
		}
		_.smartButtonImages = [];
	}

	// watch the viewport while smart buttons are on: adaptive height and lazy
	// images change its height without changing its width, and window:resize is
	// width-only by design, so nothing else reports it.
	#syncViewportObserver() {
		const _ = this;

		if (!_.navOptions.smartButtons || !_.ctx.viewport) {
			_.#disconnectViewportObserver();
			return;
		}
		if (_.viewportObserver) return;

		_.viewportObserver = new ResizeObserver(() => _.#scheduleSmartButtonsUpdate());
		_.viewportObserver.observe(_.ctx.viewport);
	}

	#disconnectViewportObserver() {
		const _ = this;
		if (!_.viewportObserver) return;
		_.viewportObserver.disconnect();
		_.viewportObserver = null;
	}

	// defer updateSmartButtons by one rAF so the FrameEngine's rAF has a chance
	// to paint the new --tarot-slide-width before we measure the image height.
	// otherwise a fast resize reads a stale offsetHeight and the button lands high.
	#scheduleSmartButtonsUpdate() {
		const _ = this;

		// smart positioning is opt-in (default off) and this is called on every
		// render-index change — check the option before booking a frame so a plain
		// carousel never schedules rAF work or measures the DOM to do nothing
		if (!_.navOptions.smartButtons) {
			if (_.smartButtonsRaf) {
				cancelAnimationFrame(_.smartButtonsRaf);
				_.smartButtonsRaf = 0;
			}
			// the option may have just been turned off — hand position back to CSS
			_.prevButton?.classList.remove('tarot-smart-position');
			_.nextButton?.classList.remove('tarot-smart-position');
			return;
		}

		if (_.smartButtonsRaf) cancelAnimationFrame(_.smartButtonsRaf);
		_.smartButtonsRaf = requestAnimationFrame(() => {
			_.smartButtonsRaf = 0;
			_.updateSmartButtons();
		});
	}

	// smart buttons place the buttons vertically only — centred on the tallest
	// image on the current page rather than on the viewport, so a captioned card
	// doesn't push them low. horizontal position stays with CSS.
	updateSmartButtons() {
		const _ = this;
		const buttons = [_.prevButton, _.nextButton];

		// hand positioning back to CSS if not using smart buttons — checked before
		// any DOM measurement so the disabled path costs nothing
		if (!_.navOptions.smartButtons) {
			for (const button of buttons) button?.classList.remove('tarot-smart-position');
			return;
		}

		const viewport = _.ctx.viewport;

		// bail if we don't have a viewport or any slides
		if (!viewport) return;
		if (!_.ctx.store.getSlides().length) return;

		// read computed styles in case we need padding
		const viewportTopPadding = parseInt(window.getComputedStyle(viewport).paddingTop) || 0;

		// figure out a rough button vertical position. with several slides in view
		// the images can differ, so the buttons have to clear the tallest.
		let buttonTopPos = viewport.offsetHeight;
		const tallestImage = _.#measurePageImages(_.#slidesOnCurrentPage());

		// only lift the buttons when the images are shorter than the viewport
		if (tallestImage > 0 && tallestImage < buttonTopPos) {
			buttonTopPos = tallestImage + viewportTopPadding * 2;
		}

		// half it so it's approximately centered (vertical only — user controls
		// horizontal via CSS)
		buttonTopPos = buttonTopPos / 2;

		for (const button of buttons) {
			if (!button) continue;
			button.classList.add('tarot-smart-position');
			button.style.top = `${buttonTopPos}px`;
		}
	}

	/**
	 * check and update disabled state of buttons
	 */
	checkDisabledState() {
		const _ = this;
		const { pageIndex, pageCount, slideCount, canLoop } = _.ctx.store.getState();

		// no slides or a single page disables both; looping never disables either
		const inert = slideCount === 0 || pageCount <= 1;

		if (_.prevButton) _.prevButton.disabled = inert || (!canLoop && pageIndex === 0);
		if (_.nextButton) {
			_.nextButton.disabled = inert || (!canLoop && pageIndex === pageCount - 1);
		}
	}

	/**
	 * destroy the buttons, unbinding all events
	 */
	destroy() {
		const _ = this;

		for (const [button, type, handler, capture] of _.#buttonListeners()) {
			button?.removeEventListener(type, handler, capture);
		}
		for (const [event, handler] of _.#subscriptions()) {
			_.ctx.emitter.off(event, handler);
		}
		_.#releasePageImages();
		_.#disconnectViewportObserver();

		// cancel debounced functions
		_.handlers.debouncedCheckDisabledState.cancel();
		_.handlers.windowResize.cancel();

		// cancel pending smart-buttons rAF
		if (_.smartButtonsRaf) {
			cancelAnimationFrame(_.smartButtonsRaf);
			_.smartButtonsRaf = 0;
		}

		// cancel pending init timers so they can't fire after teardown
		_.initTimers.forEach(clearTimeout);
		_.initTimers.length = 0;

		_.prevButton = null;
		_.nextButton = null;
	}
}
