import PhysicsEngine from './lib/physics-engine.js';
import MomentumEngine from './lib/momentum-engine.js';
import SettleEngine from './lib/settle-engine.js';
import {
	getTrackPosForIndex,
	getIndexForTrackPos,
	getTrackGeometry,
	percentToTrackPos,
	projectMomentumTarget,
	rubberband,
	inverseRubberband,
} from './utils/track-math.js';

// Velocity thresholds for gear shifts
const SNAP_THRESHOLD = 14; // Velocity below which snap kicks in (for snap: 'slide')
const STOP_THRESHOLD = 0.01; // Velocity below which we consider stopped (for snap: 'none')

// Edge overscroll spring — deliberately fixed rather than following the user's
// animation settings, so the edges always bounce even when the configured
// spring is overdamped (ζ ≥ 1, e.g. friction ≥ ~0.276 at default attraction).
// ζ = −ln(1−friction) / (2·√attraction) ≈ 0.70 → one clean visible bounce,
// second swing ~4% of the first (reads as a single bounce, not a wobble).
// Exported so the tuning invariants stay pinned in test/unit/edge-overscroll.test.js
export const EDGE_ATTRACTION = 0.05;
export const EDGE_FRICTION = 0.27;
// Peak overshoot per unit of handoff velocity for the tuning above, with
// φ = atan(√(1−ζ²)/ζ): (1/ωd)·exp(−(ζ/√(1−ζ²))·φ)·sin(φ) ≈ 2.05 px per px-per-frame
export const EDGE_OVERSHOOT_PER_VELOCITY = 2.05;
// The bounce never travels further past the edge than this fraction of the viewport
const EDGE_MAX_OVERSHOOT_RATIO = 0.25;

// Manages track animations using physics-based motion
export default class TrackAnimator {
	#currentPos = 0;
	#dragStartPos = 0;
	#targetPos = 0;
	#movementType = '';
	#direction = 0;
	#driveMovementType = 'scroll';

	// Transmission pattern: which gear is engaged and ticking
	/** @type {'idle'|'spring'|'momentum'|'settle'|'drive'|'edge'} */
	#gear = 'idle';
	#momentumEngine = null;
	#settleEngine = null;
	#edgeEngine = null;

	/**
	 * @param {Object} ctx - The context object containing carousel references and services
	 */
	constructor(ctx) {
		const _ = this;
		_.ctx = ctx;
		const emitter = ctx.emitter;

		// get initial animation options from store
		const options = _.ctx.store.getOptions();

		// load new physics engine with attraction and friction options
		_.engine = new PhysicsEngine({
			attraction: options.animation.attraction,
			friction: options.animation.friction,
			velocityBoost: options.animation.velocityBoost,
		});

		// create momentum engine for free scroll modes
		_.#momentumEngine = new MomentumEngine({
			friction: options.animation.freeScrollFriction,
		});

		// create settle engine for smooth snap-to-slide settling
		_.#settleEngine = new SettleEngine();

		// create edge-bounce spring for non-loop overscroll — fixed tuning,
		// independent of the user's animation options (see optionsChanged).
		// velocityBoost stays 1: the drag velocity is already boosted at
		// release, and boosting again would exaggerate the overshoot
		_.#edgeEngine = new PhysicsEngine({
			attraction: EDGE_ATTRACTION,
			friction: EDGE_FRICTION,
			velocityBoost: 1,
		});

		// Define event handlers to enable proper cleanup
		_.handlers = {
			optionsChanged: ({ currentOptions }) => {
				// options are always merged from OptionsManager defaults, so these values exist.
				// the edge engine is deliberately not updated here — its tuning is fixed
				// so edge overscroll always bounces regardless of user animation settings
				_.engine.setAttraction(currentOptions.animation.attraction);
				_.engine.setFriction(currentOptions.animation.friction);
				_.engine.setVelocityBoost(currentOptions.animation.velocityBoost);
				_.#momentumEngine.setFriction(currentOptions.animation.freeScrollFriction);
			},
			dragStart: ({ event }) => {
				_.stop();
				// if the track is grabbed while already overscrolled (e.g. mid-bounce),
				// anchor the drag origin in unresisted coordinates so the rubber-band
				// isn't applied on top of an already-resisted position
				_.#dragStartPos = _.#mapAcrossEdges(_.#currentPos, inverseRubberband);

				emitter.emit(_.ctx.events.user.interacted, { via: 'drag', event });
			},
			dragMove: ({ event, drag }) => {
				// direction = 0 for drag; past a non-loop edge the raw position is
				// rubber-banded so the track moves less than the finger
				_.setPos(_.#mapAcrossEdges(_.#dragStartPos + drag.delta, rubberband), 1, null, 'drag', 0);
				emitter.emit(_.ctx.events.user.interacted, { via: 'drag', event });
			},
			dragEnd: ({ event, drag }) => {
				emitter.emit(_.ctx.events.user.interacted, { via: 'drag', event });

				const options = _.ctx.store.getOptions();

				if (Math.abs(drag.delta) < options.dragThreshold) {
					_.ctx.commands.settleTrack();
					return;
				}

				// Check snap mode to determine behavior
				if (options.snap === 'page') {
					// Current behavior - go to next/previous page
					if (drag.delta < 0) {
						_.ctx.commands.next(drag.velocity);
					} else {
						_.ctx.commands.previous(drag.velocity);
					}
				} else {
					// Free scroll modes ('slide' or 'none')
					// Start momentum engine with current position and velocity
					_.startMomentum(_.#currentPos, drag.velocity * 1.3);
				}
			},
			enginePositionChanged: ({ positionDelta, progress, velocity }) => {
				if (progress === 1) {
					// we have reached the end
					_.setPos(_.#targetPos, progress, velocity, _.#movementType, _.#direction);
				} else {
					// add delta to current position
					_.setPos(
						_.#currentPos + positionDelta,
						progress,
						velocity,
						_.#movementType,
						_.#direction
					);
				}
			},
			engineMovementFinished: () => {
				_.#gear = 'idle';
				_.#emitMovementCompleted(_.#movementType);
			},
		};

		_.init();
	}

	/**
	 * Advance whichever gear is engaged by one frame.
	 * Called by FrameEngine (via its injected tickAnimation pipeline hook) while animating.
	 * @param {number} time - rAF timestamp from the frame engine
	 */
	tick(time) {
		const _ = this;

		switch (_.#gear) {
			case 'momentum':
				_.#momentumEngine.tick(time);

				// Update track position, then check for gear shift conditions
				_.setPos(_.#momentumEngine.position, 0, _.#momentumEngine.velocity, 'momentum', 0);
				_.#checkMomentumTransition();
				break;

			case 'settle':
				// Settle gear - adaptive friction settling
				_.#settleEngine.tick(time);
				break;

			case 'edge':
				// Edge gear - overscroll bounce spring
				_.#edgeEngine.tick(time);
				break;

			case 'drive':
				// Drive gear - no-op; position is driven externally
				break;

			default:
				// 'spring' or 'idle' — the spring engine no-ops when not animating,
				// so ticking it in neutral is safe and preserves any in-flight spring
				_.engine.tick(time);
		}
	}

	init() {
		this.bindEvents();
	}

	bindEvents() {
		const _ = this;
		const { emitter, events } = _.ctx;

		// Bind context events using handlers object for proper cleanup
		emitter.on(events.store.optionsChanged, _.handlers.optionsChanged);
		emitter.on(events.drag.start, _.handlers.dragStart);
		emitter.on(events.drag.move, _.handlers.dragMove);
		emitter.on(events.drag.end, _.handlers.dragEnd);

		// Bind physics engine events
		_.engine.on('engine:position-changed', _.handlers.enginePositionChanged);
		_.engine.on('engine:finished', _.handlers.engineMovementFinished);

		// Bind settle + edge engine events — the shared spring handlers are safe
		// here because only one engine runs at a time and they read #targetPos /
		// #movementType, which the settle/edge handoffs set before animating
		_.#settleEngine.on('engine:position-changed', _.handlers.enginePositionChanged);
		_.#settleEngine.on('engine:finished', _.handlers.engineMovementFinished);
		_.#edgeEngine.on('engine:position-changed', _.handlers.enginePositionChanged);
		_.#edgeEngine.on('engine:finished', _.handlers.engineMovementFinished);
	}

	// @returns {number} - The current X position.
	get currentPos() {
		return this.#currentPos;
	}

	/**
	 * Sync renderIndex and pageIndex from a track position
	 * Used by driveTrackPosition and momentum to keep indices current
	 * @param {number} position - Current track position (post-shift)
	 * @param {number} [velocity=0] - Current velocity for direction bias
	 */
	syncIndicesFromPosition(position, velocity = 0) {
		const _ = this;
		const state = _.ctx.store.getState();
		const widths = _.ctx.store.getWidths();
		const options = _.ctx.store.getOptions();
		const currentIndex = getIndexForTrackPos(position, widths, options, velocity, state.slideCount);
		const slidesPerMove = options.slidesPerMove || 1;
		const currentPageIndex = Math.max(
			0,
			Math.min(Math.floor(currentIndex / slidesPerMove), state.pageCount - 1)
		);
		if (currentIndex !== state.renderIndex || currentPageIndex !== state.pageIndex) {
			_.ctx.store.setState({
				renderIndex: currentIndex,
				pageIndex: currentPageIndex,
			});
		}
	}

	getIsAnimating() {
		return (
			this.engine.isAnimating() ||
			this.#momentumEngine.isRunning ||
			this.#settleEngine.isRunning ||
			this.#edgeEngine.isAnimating()
		);
	}

	stop() {
		const _ = this;
		_.engine.stop();
		_.#momentumEngine.stop();
		_.#settleEngine.stop();
		_.#edgeEngine.stop();
		_.#gear = 'idle';
		_.ctx.store.setAnimation({ isAnimating: false });
	}

	goToPosition(targetPos, velocity, movementType, direction = 0) {
		const _ = this;

		// don't interrupt if we're already animating to this exact position
		if (movementType !== 'jump' && _.engine.isAnimating() && _.#targetPos === targetPos) {
			return;
		}

		// stop any current animations
		_.stop();

		// save movement type and direction for later
		_.#movementType = movementType;
		_.#direction = direction;

		// check to see if it's a jump and then exit
		if (movementType === 'jump') {
			_.#emitMovementStarted(0, 'jump');
			_.setPos(targetPos, 1, 0, 'jump', direction);
			_.#emitMovementCompleted('jump');
			return;
		}

		// save target position
		_.#targetPos = targetPos;

		// engage spring gear and tell engine to go to target with velocity
		_.#gear = 'spring';
		_.engine.animateTo(_.#currentPos, targetPos, velocity);

		// emit movement started event
		_.#emitMovementStarted(velocity, movementType);
	}

	// movementType = 'animate', 'jump', 'settle', 'drag', 'scroll'
	setPos(newPosition, progress, velocity = 0, movementType, direction = null) {
		const _ = this;
		let trackDelta = newPosition - _.#currentPos;

		// final delta is 0 for completed non-continuous movements
		if (movementType !== 'drag' && movementType !== 'scroll' && progress === 1) {
			trackDelta = 0;
		}

		// save new position
		_.#currentPos = newPosition;

		// check for automatic loop shifting (only if loop is enabled)
		// the valid window is anchored to firstSnapPoint (nonzero with
		// paddingLeft/align:'center') so page 0's rest position never
		// gets shifted into the loop seam and trackPercent stays in range
		const state = _.ctx.store.getState();
		if (state.canLoop) {
			const trackWidth = _.ctx.store.getWidths().track;
			const firstSnap = Number.isFinite(state.firstSnapPoint) ? state.firstSnapPoint : 0;

			if (_.#currentPos > firstSnap) {
				// track has moved too far right, shift forwards (left)
				_.shiftTrack('forwards');
			} else if (_.#currentPos <= firstSnap - trackWidth) {
				// track has moved too far left, shift backwards (right)
				_.shiftTrack('backwards');
			}
		}

		// update track position in animation data
		_.ctx.store.setAnimation({
			movementType: movementType,
			trackPosition: _.#currentPos,
			trackDelta,
			velocity,
			progress,
			isAnimating: _.getIsAnimating(),
			direction: direction !== null ? direction : _.#direction,
		});
	}

	// direction = 'forwards' (shift left, towards negative) or 'backwards' (shift right)
	shiftTrack(direction) {
		const _ = this;
		const trackWidth = _.ctx.store.getWidths().track;
		const shiftAmount = direction === 'forwards' ? -trackWidth : trackWidth;

		// shift track by full length
		_.#currentPos += shiftAmount;
		_.#dragStartPos += shiftAmount;
		_.#targetPos += shiftAmount;

		// Also shift the engaged engine's position if running
		if (_.#gear === 'momentum' && _.#momentumEngine.isRunning) {
			_.#momentumEngine.shiftPosition(shiftAmount);
		} else if (_.#gear === 'settle' && _.#settleEngine.isRunning) {
			_.#settleEngine.shiftPosition(shiftAmount);
		} else if (_.#gear === 'edge' && _.#edgeEngine.isAnimating()) {
			// unreachable today (edge gear only engages when !canLoop) but kept
			// in step with the other gears in case that ever changes
			_.#edgeEngine.shiftPosition(shiftAmount);
		} else if (_.engine.isAnimating()) {
			_.engine.shiftPosition(shiftAmount);
		}

		// emit track shift event
		_.ctx.emitter.emit(_.ctx.events.track.shifted, {
			trackPosition: _.#currentPos,
			movementType: 'shift',
		});
	}

	/**
	 * Engage momentum gear - for free scroll drag end
	 * @param {number} position - Current track position
	 * @param {number} velocity - Initial velocity from drag
	 */
	startMomentum(position, velocity) {
		const _ = this;

		// Stop any current animation
		_.stop();

		// Start momentum engine
		_.#momentumEngine.start(position, velocity);
		_.#gear = 'momentum';
		_.#movementType = 'momentum';

		// Update store to trigger frame loop (isAnimating becomes true)
		_.setPos(position, 0, velocity, 'momentum', 0);

		// Emit movement started
		_.#emitMovementStarted(velocity, 'momentum');
	}

	/**
	 * Drive track position — self-contained, no session management.
	 * Plugins describe intent (deltaPx or positionPercent), core handles positioning.
	 * Auto-engages on first call, auto-disengages when stop() is called or movementType is 'settle'.
	 * @param {Object} params
	 * @param {number} [params.deltaPx] - Relative pixel movement ("move by N px this frame")
	 * @param {number} [params.positionPercent] - Absolute 0-1 track position
	 * @param {number} [params.velocity=0] - Current velocity for direction bias
	 * @param {string} [params.movementType='scroll'] - Movement type ('scroll' or 'settle')
	 */
	drivePosition({ deltaPx, positionPercent, velocity = 0, movementType = 'scroll' }) {
		const _ = this;

		// Settle: disengage drive and snap to nearest page
		if (movementType === 'settle') {
			_.#gear = 'idle';
			_.ctx.commands.settleTrack();
			return;
		}

		// Resolve position from intent — bail if no position data provided
		let position;
		if (deltaPx !== undefined) {
			position = _.#currentPos + deltaPx;
		} else if (positionPercent !== undefined) {
			position = _.#resolvePercentToPosition(positionPercent);
		} else {
			return;
		}

		// Auto-engage drive gear on first call (after validation)
		if (_.#gear !== 'drive') {
			_.stop();
			_.#gear = 'drive';
			_.#driveMovementType = movementType;
		}

		const direction = velocity !== 0 ? Math.sign(velocity) : Math.sign(position - _.#currentPos);
		_.setPos(position, 1, velocity, _.#driveMovementType, direction);
		_.syncIndicesFromPosition(_.#currentPos, velocity);
	}

	/**
	 * Resolve a 0-1 percent to an absolute track position (loop-aware)
	 * @param {number} percent - 0-1 position (can overflow for loop seam transitions)
	 * @returns {number} Track position in pixels
	 */
	#resolvePercentToPosition(percent) {
		const geometry = getTrackGeometry(this.ctx.store.getState(), this.ctx.store.getWidths());
		return percentToTrackPos(percent, geometry);
	}

	/**
	 * Check if momentum engine should transition to physics (snap) or stop
	 * Called each frame when momentum gear is engaged
	 */
	#checkMomentumTransition() {
		const _ = this;
		const velocity = _.#momentumEngine.velocity;
		let position = _.#momentumEngine.position;
		const options = _.ctx.store.getOptions();
		const widths = _.ctx.store.getWidths();
		const state = _.ctx.store.getState();
		const slideCount = state.slideCount;

		// Boundary handling for non-looping carousels: overshoot past the edge
		// and spring back (iOS-style overscroll) instead of hard-clamping.
		// getTrackPosForIndex accounts for padding, centering, and other layout
		// options; positions are negated screen offsets, so the start edge is
		// the numerically largest valid position and the end edge the smallest
		if (!state.canLoop) {
			const startEdgePos = getTrackPosForIndex(0, widths, options, state);
			const endEdgePos = getTrackPosForIndex(slideCount - 1, widths, options, state);

			// where momentum would naturally coast to (same projection as
			// projectMomentumTarget): position + v · f/(1−f) for per-frame decay f
			const friction = Math.min(options.animation?.freeScrollFriction || 0.96, 0.999);
			const naturalStop = position + velocity * (friction / (1 - friction));

			if (position > startEdgePos) {
				// past the start edge — but if momentum is heading back inside and
				// will coast past the edge on its own, let it run (this re-runs
				// every tick, so a weak inward flick still springs once it decays)
				if (velocity < 0 && naturalStop < startEdgePos) {
					_.syncIndicesFromPosition(position, velocity);
					return;
				}
				_.#startEdgeSpring(startEdgePos, velocity);
				return;
			} else if (position < endEdgePos) {
				if (velocity > 0 && naturalStop > endEdgePos) {
					_.syncIndicesFromPosition(position, velocity);
					return;
				}
				_.#startEdgeSpring(endEdgePos, velocity);
				return;
			}
		}

		if (options.snap === 'slide' && Math.abs(velocity) < SNAP_THRESHOLD) {
			// GEAR SHIFT: Momentum → Settle (adaptive friction)
			_.#momentumEngine.stop();

			// Snap policy lives in track math (see projectMomentumTarget) — this
			// method only executes the resulting motion
			const target = projectMomentumTarget(position, velocity, widths, options, state);

			// zero-width layout (e.g. carousel inside display:none at init) —
			// no geometry to project onto; stop in place instead of dividing
			// by zero and writing Infinity/NaN indices into the store
			if (!target) {
				_.syncIndicesFromPosition(position, 0);
				_.#gear = 'idle';
				_.setPos(position, 1, 0, 'momentum', 0);
				_.#emitMovementCompleted('momentum');
				return;
			}

			const distanceToTarget = Math.abs(target.position - position);

			// Update state BEFORE emitting any events
			_.ctx.store.setState({
				renderIndex: target.index,
				pageIndex: target.pageIndex,
			});

			// two-phase event contract: close the momentum phase and open the
			// settle phase so every movement:started has a matching
			// movement:completed of the same type
			_.#emitMovementCompleted('momentum');
			_.#emitMovementStarted(velocity, 'settle');

			// If we're already very close to target, just snap there immediately
			if (distanceToTarget < 5) {
				_.setPos(target.position, 1, 0, 'settle', 0);
				_.#gear = 'idle';
				_.#emitMovementCompleted('settle');
				return;
			}

			// Engage settle gear with adaptive friction for smooth iOS-like landing
			_.#targetPos = target.position;
			_.#movementType = 'settle';
			_.#settleEngine.start(position, velocity, target.position);
			_.#gear = 'settle';
		} else if (options.snap === 'none' && Math.abs(velocity) < STOP_THRESHOLD) {
			// NEUTRAL: Just stop wherever we are
			_.syncIndicesFromPosition(position, velocity);
			_.#momentumEngine.stop();
			_.#gear = 'idle';
			_.setPos(position, 1, 0, 'momentum', 0);
			_.#emitMovementCompleted('momentum');
		} else {
			// Still in momentum — sync indices for live updates
			_.syncIndicesFromPosition(position, velocity);
		}
	}

	/**
	 * Hand off from momentum to the edge-bounce spring: the track overshoots
	 * the edge with the surviving velocity and settles back (iOS overscroll).
	 * Also covers a drag released out of bounds — the spring starts from the
	 * actual current position, so distance already past the edge becomes
	 * initial displacement and the track springs back from wherever it was.
	 * @param {number} edgePos - Track position of the start or end edge
	 * @param {number} velocity - Surviving momentum velocity (px per frame)
	 */
	#startEdgeSpring(edgePos, velocity) {
		const _ = this;

		// cap the handoff velocity so peak overshoot (≈2.05·v at the edge
		// tuning) never exceeds a fraction of the viewport, no matter how
		// violent the flick
		const viewport = _.ctx.store.getWidths().viewport;
		const velocityCap = (viewport * EDGE_MAX_OVERSHOOT_RATIO) / EDGE_OVERSHOOT_PER_VELOCITY;
		const cappedVelocity = Math.max(-velocityCap, Math.min(velocity, velocityCap));

		_.#momentumEngine.stop();

		// the edge is slide 0 / last slide's rest position — sync indices
		// before emitting so listeners read the final renderIndex from state
		_.syncIndicesFromPosition(edgePos, 0);

		// two-phase event contract: close the momentum phase and open the
		// settle phase so every movement:started has a matching
		// movement:completed of the same type
		_.#emitMovementCompleted('momentum');

		_.#targetPos = edgePos;
		_.#movementType = 'settle';
		_.#direction = Math.sign(edgePos - _.#currentPos) || 0;
		_.#gear = 'edge';
		_.#edgeEngine.animateTo(_.#currentPos, edgePos, cappedVelocity);
		_.#emitMovementStarted(cappedVelocity, 'settle');
	}

	/**
	 * Apply the rubber-band curve to the part of a position that sits past a
	 * non-loop edge. In-bounds positions and loop mode pass through 1:1.
	 *
	 * `map` picks the direction of the mapping, and the two are exact inverses:
	 * - `rubberband` turns a raw drag position (dragStartPos + delta) into the
	 *   resisted position to render, so the track moves progressively less than
	 *   the finger the further it is pulled
	 * - `inverseRubberband` turns an on-screen (possibly resisted) position back
	 *   into unresisted drag coordinates, which is what the drag origin needs to
	 *   be when a drag starts while the track is already overscrolled — so the
	 *   first move neither jumps nor double-applies the resistance
	 *
	 * @param {number} pos - Position to map
	 * @param {Function} map - rubberband or inverseRubberband
	 * @returns {number} Mapped position
	 */
	#mapAcrossEdges(pos, map) {
		const _ = this;
		const state = _.ctx.store.getState();
		if (state.canLoop || !state.slideCount) return pos;

		const widths = _.ctx.store.getWidths();
		const options = _.ctx.store.getOptions();
		const startEdgePos = getTrackPosForIndex(0, widths, options, state);
		const endEdgePos = getTrackPosForIndex(state.slideCount - 1, widths, options, state);

		if (pos > startEdgePos) {
			return startEdgePos + map(pos - startEdgePos, widths.viewport);
		}
		if (pos < endEdgePos) {
			return endEdgePos - map(endEdgePos - pos, widths.viewport);
		}
		return pos;
	}

	#emitMovementStarted(velocity, movementType) {
		const ctx = this.ctx;
		const state = ctx.store.getState();
		ctx.emitter.emit(ctx.events.movement.started, {
			renderIndex: state.renderIndex,
			pageIndex: state.pageIndex,
			velocity,
			movementType,
		});
	}

	#emitMovementCompleted(movementType) {
		const ctx = this.ctx;
		const state = ctx.store.getState();
		ctx.emitter.emit(ctx.events.movement.completed, {
			renderIndex: state.renderIndex,
			pageIndex: state.pageIndex,
			movementType,
		});
	}

	destroy() {
		const _ = this;

		// unbind + stop every engine (the carousel destroys this animator once
		// and drops the reference, so none of these can already be gone)
		_.engine.off('engine:position-changed', _.handlers.enginePositionChanged);
		_.engine.off('engine:finished', _.handlers.engineMovementFinished);
		_.engine.stop();
		_.engine = null;

		_.#momentumEngine.stop();
		_.#momentumEngine = null;

		_.#settleEngine.off('engine:position-changed', _.handlers.enginePositionChanged);
		_.#settleEngine.off('engine:finished', _.handlers.engineMovementFinished);
		_.#settleEngine.destroy();
		_.#settleEngine = null;

		_.#edgeEngine.off('engine:position-changed', _.handlers.enginePositionChanged);
		_.#edgeEngine.off('engine:finished', _.handlers.engineMovementFinished);
		_.#edgeEngine.stop();
		_.#edgeEngine = null;

		_.#gear = 'idle';

		// remove context event listeners using specific handler references
		const { emitter, events } = _.ctx;
		emitter.off(events.store.optionsChanged, _.handlers.optionsChanged);
		emitter.off(events.drag.start, _.handlers.dragStart);
		emitter.off(events.drag.move, _.handlers.dragMove);
		emitter.off(events.drag.end, _.handlers.dragEnd);

		// clear handlers reference
		_.handlers = null;
	}
}
