// styles
import './styles/tarot-carousel.css';

// main Tarot class
import Tarot from './scripts/tarot.js';

// base effect class for external effects
import TarotEffect from './scripts/effects/tarot-effect.js';

// include custom HTML elements
import './scripts/custom-elements.js';

// Core plugins are now built-in to Tarot

/**
 * Register everything queued on a global before Tarot loaded, then replace that
 * global with a push proxy so anything loading later registers immediately.
 * @param {string} queueName - global queue name ('TarotEffectQueue' | 'TarotPluginQueue')
 * @param {Function} register - registers one queued item
 */
function drainQueue(queueName, register) {
	if (typeof window === 'undefined') return;

	const queued = window[queueName];
	if (Array.isArray(queued)) queued.forEach((item) => register(item));

	window[queueName] = { push: register };
}

drainQueue('TarotEffectQueue', (item) => {
	// Factory pattern: build the class against our base, then register
	if (item && item.factory) Tarot.registerEffect(item.factory(TarotEffect));
	// Legacy: direct class
	else if (typeof item === 'function') Tarot.registerEffect(item);
});

drainQueue('TarotPluginQueue', (item) => {
	if (item && item.plugin) Tarot.registerPlugin(item.plugin);
	else if (typeof item === 'function') Tarot.registerPlugin(item);
});

// register as custom element (guarded for hot reload / duplicate script
// loads, and for Node where customElements doesn't exist)
if (typeof customElements !== 'undefined' && !customElements.get('tarot-carousel')) {
	customElements.define('tarot-carousel', Tarot);
}

// Export everything as named exports (modern ESM pattern)
export { Tarot as default }; // Main class as default export
export { Tarot, TarotEffect }; // Base class for effects
