/*
	Cross-carousel sync plugin — one connection engine, two modes:

	- asNavFor (nav mode): mirrors the target's movement onto this carousel with
	  a plain centered animation, pushes this carousel's selection back to the
	  target, and adds the nav UI — tablist roles, roving tabindex, keyboard
	  navigation and focus on click. Compares against selectedIndex.
	- syncWith: mirrors movement requests in both directions, preserving the
	  original velocity and movement type. Compares against renderIndex. No UI.

	Both options may be set on the same carousel. The registered instance runs
	nav mode and owns a second instance for syncWith mode, so each connection
	keeps its own echo guard and timers and a movement arriving over one
	connection still relays out over the other.
*/

/** Per-mode wiring: option key, connect delay, warning label. */
const MODES = {
	asNavFor: { option: 'asNavFor', delay: 40, label: 'AsNavFor' },
	syncWith: { option: 'syncWith', delay: 100, label: 'SyncWith' },
};

export default class AsNavFor {
	static pluginName = 'as-nav-for';

	/**
	 * @constructor
	 * @param {Object} ctx - the carousel context that will be synced with another
	 * @param {'asNavFor'|'syncWith'} [mode='asNavFor'] - which option this
	 *   instance connects; only the nav-mode instance is registered as a plugin
	 */
	constructor(ctx, mode = 'asNavFor') {
		const _ = this;
		_.ctx = ctx;
		_.mode = MODES[mode];
		_.isNav = mode === 'asNavFor';
		_.otherCarousel = null;
		_.isActive = false; // nav mode: asNavFor is configured and the target was found
		_.isSyncing = false; // guards against sync echo loops
		_.connectTimer = null;
		_.focusTimers = new Set();
		_.mirrorTimers = new Map(); // timer → callback, so reInit can flush instead of drop

		// define all event handlers in one object
		_.handlers = {
			// handler for other carousel's movement requested event
			otherMovementRequested: ({ index, velocity, movementType }) => {
				// ignore echoes of a sync we initiated/are processing
				if (_.isSyncing) return;
				// nav mode tracks the logical selection, syncWith what is rendered
				const state = _.ctx.store.getState();
				const currentIndex = _.isNav ? state.selectedIndex : state.renderIndex;
				// return if we are already going to that index or already at it
				if (currentIndex === index) return;

				_.isSyncing = true;
				const run = () => {
					_.mirrorTimers.delete(timer);
					// nav always centers on a plain animation; syncWith keeps the
					// velocity and movement type of the original request
					if (_.isNav) _.ctx.commands.goToSlide(index);
					else _.ctx.commands.goToSlide(index, velocity, movementType);
					_.isSyncing = false;
				};
				const timer = setTimeout(run, 1);
				_.mirrorTimers.set(timer, run);
			},

			// handler for carousel's optionsChanged event
			// (disconnect or connect to a new carousel)
			optionsChanged: () => {
				_.reInit();
			},

			// syncWith: push this carousel's movement request to the other one
			movementRequested: ({ index, velocity, movementType }) => {
				if (_.isSyncing) return; // prevent re-entry from sync loop
				if (!_.otherCarousel) return;

				_.isSyncing = true;
				const run = () => {
					_.mirrorTimers.delete(timer);
					if (typeof _.otherCarousel?.goToSlide !== 'function') {
						_.isSyncing = false;
						return;
					}
					_.otherCarousel.goToSlide(index, velocity, movementType);
					_.isSyncing = false;
				};
				const timer = setTimeout(run, 1);
				_.mirrorTimers.set(timer, run);
			},

			// keep selectedIndex in lockstep with renderIndex (only when active)
			renderIndexChanged: ({ currentIndex }) => {
				if (!_.isActive) return;
				const state = _.ctx.store.getState();
				if (state.selectedIndex !== currentIndex) {
					_.ctx.store.setState({ selectedIndex: currentIndex });
				}
			},

			slidesChanged: () => {
				if (_.isActive) _.applyNavRoles();
			},

			// handler for carousel's selectedIndexChanged event
			selectedIndexChanged: ({ previousIndex, currentIndex }) => {
				if (!_.isActive) return;
				_.updateOtherCarousel();
				_.updateNavClasses(previousIndex, currentIndex);
			},

			// handler for keyboard navigation
			keyDown: (event) => {
				if (!_.isActive) return;
				_.handleKeyDown(event);
			},

			// handler for slide clicks (nav-specific)
			slideClick: ({ index }) => {
				if (!_.isActive) return;
				// Focus the clicked slide for consistent keyboard capture
				_.ctx.store.getSlides()[index]?.focus({ preventScroll: true });
				// When nav slide is clicked, go to that slide and update main carousel
				_.ctx.commands.goToSlide(index);
			},
		};

		_.init();

		// syncWith rides along on its own connection, so a carousel can use both
		// options at once without the two sharing an echo guard
		if (_.isNav) _.syncLink = new AsNavFor(ctx, 'syncWith');
	}

	/**
	 * query the other carousel from the DOM
	 * @returns {boolean} whether a target was found
	 */
	queryDOM() {
		const _ = this;
		const selector = _.ctx.store.getOptions()[_.mode.option];

		// exit (and disable) if no value, or the target can't be found — only
		// restore ARIA if nav was actually active; plain carousels shouldn't get
		// slide ARIA churn on every options change
		if (!selector) {
			_.deactivateNavUI();
			return false;
		}

		const otherCarousel = document.querySelector(selector);
		if (!otherCarousel) {
			_.deactivateNavUI();
			return false;
		}

		_.otherCarousel = otherCarousel;
		if (_.isNav) _.isActive = true;
		return true;
	}

	/**
	 * initialize the sync functionality and (in nav mode) nav-specific features
	 */
	init() {
		this.bindEvents();
		this.setupConnection();
	}

	/**
	 * setup the connection to the other carousel
	 * Called from init() and reInit()
	 */
	setupConnection() {
		const _ = this;

		if (!_.queryDOM()) return;

		// Add nav-specific styling + keyboard
		if (_.isNav) _.enableNavUI();

		// give DOM a few ms to load the custom elements
		_.connectTimer = setTimeout(async () => {
			_.connectTimer = null;
			try {
				// nav mode waits for the definition before probing the target
				if (_.isNav) await customElements.whenDefined('tarot-carousel');
				if (typeof _.otherCarousel?.on !== 'function') throw new Error('Target unavailable');
				_.otherCarousel.on(_.ctx.events.movement.requested, _.handlers.otherMovementRequested);
			} catch {
				console.warn(`tarot: ${_.mode.label} target is not a tarot-carousel`);
				// unwind the tablist ARIA/keyboard wiring enableNavUI already
				// applied — later cleanup paths gate on isActive and would skip
				// it — and drop the target we could not bind to, so nothing
				// downstream tries to call carousel methods on it
				if (_.isNav) {
					_.disableNavUI();
					_.isActive = false;
					_.otherCarousel = null;
				}
				return;
			}
			if (!_.isNav) return;
			// Initialize nav classes
			_.updateNavClasses(-1, _.ctx.store.getState().selectedIndex);
			// Ensure selection matches render index at startup
			const { renderIndex, selectedIndex } = _.ctx.store.getState();
			if (renderIndex !== selectedIndex) {
				_.ctx.store.setState({ selectedIndex: renderIndex });
			}
		}, _.mode.delay);
	}

	/**
	 * reinitialize on carousel option changes
	 */
	reInit() {
		const _ = this;
		// flush (not drop) pending mirrors while the old connection is still
		// valid: a movement scheduled just before an options change must still
		// reach the other carousel
		_.clearTimers(true);
		// cleanup existing connection
		if (typeof _.otherCarousel?.off === 'function') {
			_.otherCarousel.off(_.ctx.events.movement.requested, _.handlers.otherMovementRequested);
		}
		_.otherCarousel = null;
		// disable UI until proven active again — skipped when nav was never
		// active so plain carousels don't rewrite slide ARIA on every options change
		_.deactivateNavUI();
		// reinitialize connection with new options (don't rebind events)
		_.setupConnection();
	}

	/**
	 * bind carousel events to handlers
	 */
	bindEvents() {
		const _ = this;
		const { emitter, events } = _.ctx;
		const handlers = _.handlers;

		emitter.on(events.store.optionsChanged, handlers.optionsChanged);

		// syncWith only mirrors movement; nav mode drives off the selection and
		// owns the tablist UI
		if (!_.isNav) {
			emitter.on(events.movement.requested, handlers.movementRequested);
			return;
		}
		emitter.on(events.store.renderIndexChanged, handlers.renderIndexChanged);
		emitter.on(events.store.selectedIndexChanged, handlers.selectedIndexChanged);
		emitter.on(events.store.slidesChanged, handlers.slidesChanged);
		emitter.on(events.slides.click, handlers.slideClick);
	}

	/** enable nav-specific UI and keyboard only when active */
	enableNavUI() {
		const _ = this;
		const ctx = _.ctx;
		const carousel = ctx.carousel;
		if (!_.isActive) return;
		carousel.classList.add('tarot-nav-carousel');
		ctx.track.addEventListener('keydown', _.handlers.keyDown, true);
		carousel.setAttribute('tabindex', '0');
		carousel.setAttribute('role', 'tablist');
		carousel.setAttribute('aria-label', 'Carousel Navigation');
		carousel.removeAttribute('aria-roledescription');

		// Ensure slides have correct roles and initial roving tabindex
		_.applyNavRoles();
	}

	/** Apply tab roles and roving tabindex to the current slide collection. */
	applyNavRoles() {
		const _ = this;
		const slides = _.ctx.store.getSlides();
		const sel = _.ctx.store.getState().selectedIndex;
		for (let i = 0; i < slides.length; i++) {
			const s = slides[i];
			s.setAttribute('role', 'tab');
			s.removeAttribute('aria-roledescription');
			s.setAttribute('tabindex', i === sel ? '0' : '-1');
		}
	}

	/** tear the nav UI back down, but only if it was ever applied */
	deactivateNavUI() {
		const _ = this;
		if (!_.isActive) return;
		_.disableNavUI();
		_.isActive = false;
	}

	/**
	 * Schedule a focus update and retain its timer for teardown.
	 * @param {Function} callback - Focus operation
	 */
	scheduleFocus(callback) {
		const _ = this;
		const timer = setTimeout(() => {
			_.focusTimers.delete(timer);
			callback();
		}, 0);
		_.focusTimers.add(timer);
	}

	/** disable nav-specific UI and keyboard when not active */
	disableNavUI() {
		const _ = this;
		const ctx = _.ctx;
		const carousel = ctx.carousel;

		carousel.classList.remove('tarot-nav-carousel');
		ctx.track.removeEventListener('keydown', _.handlers.keyDown, true);
		// Don't remove tabindex - core carousel needs it for arrow key support
		carousel.removeAttribute('aria-label');
		carousel.setAttribute('role', 'group');
		carousel.setAttribute('aria-roledescription', 'carousel');

		// Clean up nav-specific ARIA attributes from slides
		const slides = ctx.store.getSlides();
		slides.forEach((slide) => {
			slide.removeAttribute('aria-selected');
			slide.removeAttribute('tabindex');
			slide.setAttribute('role', 'group');
			slide.setAttribute('aria-roledescription', 'slide');
		});
	}

	/**
	 * Handle keyboard navigation for nav carousel (tablist pattern):
	 * arrows step one slide, Home/End jump to the ends, and focus follows the
	 * selection. Wrapping keys off state.canLoop — the same signal the core
	 * arrows and pagination use — so a loop:true layout that cannot actually
	 * loop stops at the ends here too.
	 * @param {KeyboardEvent} event
	 */
	handleKeyDown(event) {
		const _ = this;
		const { selectedIndex, slideCount, canLoop } = _.ctx.store.getState();
		const lastIndex = slideCount - 1;
		let targetIndex;

		switch (event.key) {
			case 'ArrowLeft':
			case 'ArrowUp':
				targetIndex = selectedIndex > 0 ? selectedIndex - 1 : canLoop ? lastIndex : selectedIndex;
				break;

			case 'ArrowRight':
			case 'ArrowDown':
				targetIndex = selectedIndex < lastIndex ? selectedIndex + 1 : canLoop ? 0 : selectedIndex;
				break;

			case 'Home':
				targetIndex = 0;
				break;

			case 'End':
				targetIndex = lastIndex;
				break;

			default:
				return;
		}

		event.preventDefault();
		event.stopPropagation(); // prevent core carousel arrow handling

		_.ctx.commands.goToSlide(targetIndex);

		// move focus to the newly selected tab (slides are re-read after the
		// move so a re-render can't leave us focusing a detached element)
		const targetSlide = _.ctx.store.getSlides()[targetIndex];
		if (targetSlide) _.scheduleFocus(() => targetSlide.focus({ preventScroll: true }));
	}

	/**
	 * Update navigation-specific classes on slides
	 * Note: The main tarot-selected class is handled by ClassManager,
	 * but we add nav-specific ARIA attributes for accessibility
	 */
	updateNavClasses(previousIndex, currentIndex) {
		const _ = this;
		const slides = _.ctx.store.getSlides();

		// Update ARIA attributes for navigation
		if (previousIndex >= 0 && slides[previousIndex]) {
			slides[previousIndex].setAttribute('aria-selected', 'false');
			// roving tabindex: make previous non-focusable
			slides[previousIndex].setAttribute('tabindex', '-1');
		}

		// Add ARIA attributes to current slide
		if (slides[currentIndex]) {
			slides[currentIndex].setAttribute('aria-selected', 'true');
			slides[currentIndex].setAttribute('role', 'tab');
			// roving tabindex: make current focusable
			slides[currentIndex].setAttribute('tabindex', '0');
		}

		// The tarot-selected class is automatically managed by ClassManager
		// based on slide.selected property, so we don't need to manually manage it here
	}

	/**
	 * update the other carousel to match this one (nav mode)
	 */
	updateOtherCarousel() {
		const _ = this;
		// return if we don't have a carousel to update
		if (!_.otherCarousel) return;

		// don't echo a selection change back while we're applying one FROM the
		// other carousel — that's how double-navigation loops start
		if (_.isSyncing) return;

		// get current selected index from store
		const currentIndex = _.ctx.store.getState().selectedIndex;
		// capture the target now — a flush during reInit must hit the carousel
		// this update was meant for, not whatever gets connected next
		const otherCarousel = _.otherCarousel;
		// tell carousel to go to the same selected index (deferred a tick)
		const run = () => {
			_.mirrorTimers.delete(timer);
			try {
				otherCarousel.goToSlide(currentIndex);
			} catch {
				// silent - other carousel may have been destroyed
			}
		};
		const timer = setTimeout(run, 1);
		_.mirrorTimers.set(timer, run);
	}

	/**
	 * Clear the pending connect timer and the movement-mirror timers.
	 * @param {boolean} [flush=false] - run pending mirrors synchronously
	 *   (reInit) instead of dropping them (destroy)
	 */
	clearTimers(flush = false) {
		const _ = this;
		if (_.connectTimer !== null) clearTimeout(_.connectTimer);
		_.connectTimer = null;
		const pending = [..._.mirrorTimers.values()];
		for (const timer of _.mirrorTimers.keys()) clearTimeout(timer);
		_.mirrorTimers.clear();
		if (flush) for (const run of pending) run();
		_.isSyncing = false;
	}

	/**
	 * destroy the sync, unbinding all events and cleaning up nav functionality
	 */
	destroy() {
		const _ = this;
		_.clearTimers();
		for (const timer of _.focusTimers) clearTimeout(timer);
		_.focusTimers.clear();

		const { emitter, events } = _.ctx;
		const handlers = _.handlers;

		// unbind from carousel events (mirrors bindEvents)
		emitter.off(events.store.optionsChanged, handlers.optionsChanged);
		if (_.isNav) {
			emitter.off(events.store.renderIndexChanged, handlers.renderIndexChanged);
			emitter.off(events.store.selectedIndexChanged, handlers.selectedIndexChanged);
			emitter.off(events.store.slidesChanged, handlers.slidesChanged);
			emitter.off(events.slides.click, handlers.slideClick);

			// Remove nav-specific UI
			_.disableNavUI();
		} else {
			emitter.off(events.movement.requested, handlers.movementRequested);
		}

		// unbind from other carousel events
		if (typeof _.otherCarousel?.off === 'function') {
			_.otherCarousel.off(events.movement.requested, handlers.otherMovementRequested);
		}

		_.otherCarousel = null;
		_.isActive = false;

		// tear down the syncWith connection this instance owns
		_.syncLink?.destroy();
	}
}
