import SlideStateManager from './slide-state-manager.js';
import { createFrameUtils } from './utils/frame-utils.js';

// consecutive render failures before a broken effect is swapped for the fallback
const MAX_RENDER_FAILURES = 3;

export default class FrameEngine {
	#slideStateManager;
	#renderFailures = 0;
	#layoutDirty = false;
	/** @type {boolean} an options:changed landed — the next flush reports carousel:reinit */
	#reinitPending = false;
	/** @type {boolean} the initial (mount) frame — and its layout flush — has already run */
	#hasFlushed = false;
	#pipeline;
	ctx;

	/**
	 * @param {object} ctx - shared module context
	 * @param {object} pipeline - privileged cross-module hooks, injected by the
	 *   carousel at construction so they never ride the plugin-facing ctx.commands:
	 * @param {Function} pipeline.tickAnimation - drive TrackAnimator physics for this frame
	 * @param {Function} pipeline.prepSlidesForFrame - SlideManager preps slide positions
	 * @param {Function} pipeline.flushLayout - LayoutEngine layout phase (recompute + effect reInit + re-jump)
	 * @param {Function} pipeline.loadFallbackEffect - swap a repeatedly-throwing effect for the core carousel
	 */
	constructor(ctx, pipeline) {
		const _ = this;
		_.ctx = ctx;
		_.#pipeline = pipeline;

		_.#slideStateManager = new SlideStateManager(ctx);

		_.effect = null;
		_.rafId = null;

		// bound once — requestFrame runs per frame, a per-request .bind() allocates needlessly
		_.boundOnFrame = (time) => _.onFrame(time);

		_.handlers = {
			effectChanged: ({ currentEffect }) => {
				_.effect = currentEffect;
				_.#renderFailures = 0;
				_.requestFrame();
			},
			storeDirty: () => {
				_.requestFrame();
			},
			layoutInvalidated: () => {
				_.#layoutDirty = true;
				_.requestFrame();
			},
			// options are the only invalidation source that counts as a
			// reconfiguration — slides and resize reflow geometry but don't
			// change how the carousel is configured
			optionsInvalidated: () => {
				_.#layoutDirty = true;
				_.#reinitPending = true;
				_.requestFrame();
			},
		};

		_.init();
	}

	init() {
		this.bindEvents();
	}

	bindEvents() {
		const { emitter, events } = this.ctx;

		// effect swapped
		emitter.on(events.effect.changed, this.handlers.effectChanged);

		// store changed → request frame
		emitter.on(events.store.changedDirty, this.handlers.storeDirty);

		// options / slides / viewport size changes invalidate layout — flushed
		// as the first phase of the next frame rather than on a timer
		emitter.on(events.store.optionsChanged, this.handlers.optionsInvalidated);
		emitter.on(events.store.slidesChanged, this.handlers.layoutInvalidated);
		emitter.on(events.window.resize, this.handlers.layoutInvalidated);
	}

	requestFrame() {
		if (this.rafId !== null) return; // already pending
		this.rafId = requestAnimationFrame(this.boundOnFrame);
	}

	cancel() {
		if (this.rafId !== null) {
			cancelAnimationFrame(this.rafId);
			this.rafId = null;
		}
	}

	onFrame(time) {
		const _ = this;

		// destroy() can race a frame already scheduled this tick
		if (!_.ctx) return;

		// Step 0: Flush any pending layout reconfiguration (options, slides,
		// resize) so nothing below reads stale geometry. rafId is deliberately
		// still set here: store writes made by the flush coalesce into this
		// frame instead of scheduling a redundant one. If the flush re-dirties
		// layout, the re-check after rafId clears schedules the follow-up frame.
		let announceReinit = false;
		if (_.#layoutDirty) {
			_.#layoutDirty = false;
			_.#pipeline.flushLayout();

			// carousel:reinit means "options genuinely changed after mount" —
			// the first flush is the initial layout, already covered by
			// carousel:ready, and resize/slide reflows aren't reconfigurations
			announceReinit = _.#reinitPending && _.#hasFlushed;
			_.#reinitPending = false;
		}

		// mount is over once the first frame has run, flush or not
		_.#hasFlushed = true;

		// clear rafId — emitting below happens with no frame pending, so a
		// listener that reconfigures the carousel can schedule the next one
		_.rafId = null;

		if (announceReinit) {
			_.ctx.emitter.emit(_.ctx.events.carousel.reinit, {});
		}

		// re-invalidated during the flush (or by a reinit listener) — make sure
		// the follow-up flush actually gets a frame instead of being swallowed
		if (_.#layoutDirty) _.requestFrame();

		// Step 1: Tell SlideManager to prep slides (updates datastore)
		_.#pipeline.prepSlidesForFrame();

		// Step 2: Get fresh snapshot with prepped slides
		const snapshot = _.ctx.store.getSnapshot();

		// Sort slides by _renderIndex (important for transform calculations)
		// Create a copy for sorting since we shouldn't mutate the original array
		const sortedSlides = [...snapshot.slides].sort((a, b) => a._renderIndex - b._renderIndex);

		// Step 3: Build frame object with all data
		const frame = Object.freeze({
			state: snapshot.state, // all carousel state: selectedIndex, renderIndex, page, etc.
			widths: snapshot.widths, // all measured widths: viewport, slide, gap, etc.
			options: snapshot.options, // current active options in datastore
			slides: sortedSlides, // prepped slides array with calculated positions
			animation: snapshot.animation, // { movementType, trackPosition, trackDelta, velocity, progress }
			transformPoints: snapshot.transformPoints, // named position points for effects
			time: time, // current animation frame timestamp from requestAnimationFrame
		});

		// render frame
		_.renderFrame(frame);

		// mark store as clean after processing
		_.ctx.store.markAsClean();

		// schedule next frame only while an animation is in progress
		if (snapshot.animation.isAnimating) {
			// Tick the track animator's physics directly — a single-consumer call,
			// not a notification, so it doesn't ride the event bus
			_.#pipeline.tickAnimation(time);

			// request next frame
			_.requestFrame();
		}
	}

	renderFrame(frame) {
		const _ = this;

		// effect is null until the first effect:changed event fires — skip the
		// frame rather than crash if the store is dirtied before the effect loads
		if (!_.effect) return;

		// emit before render event
		_.ctx.emitter.emit(_.ctx.events.frame.beforeRender, frame);

		// pass frame and utils to effect.render(frame, utils)
		// guarded so one bad effect frame can't kill the rAF loop mid-animation
		const utils = createFrameUtils(frame);
		try {
			_.effect.render(frame, utils);
			_.#renderFailures = 0;
		} catch (error) {
			_.#handleRenderError(error);
		}

		// update classes and ARIA states based on visibility in viewport
		_.#slideStateManager.updateSlides(frame.animation.trackPosition);

		// emit after render event
		_.ctx.emitter.emit(_.ctx.events.frame.afterRender, frame);
	}

	/**
	 * A throwing effect must not freeze the carousel: report the failure and,
	 * if it keeps throwing, swap to the core carousel effect so the user still
	 * has a working (if plain) carousel.
	 * @param {Error} error - the error thrown by effect.render()
	 */
	#handleRenderError(error) {
		const _ = this;
		_.#renderFailures++;

		const effectName =
			_.effect?.constructor?.effectName || _.effect?.constructor?.name || 'unknown';
		console.error(`tarot: effect '${effectName}' render failed:`, error);
		_.ctx.emitter.emit(_.ctx.events.carousel.error, {
			message: `effect '${effectName}' render failed`,
			error,
		});

		if (_.#renderFailures < MAX_RENDER_FAILURES) return;
		_.#renderFailures = 0;

		if (effectName === 'carousel') {
			// the fallback itself is broken — stop rendering rather than thrash
			_.effect = null;
			return;
		}

		console.error(`tarot: effect '${effectName}' disabled, using 'carousel'`);
		_.#pipeline.loadFallbackEffect();
	}

	destroy() {
		const _ = this;
		const { emitter, events } = _.ctx;

		// Cancel any pending animation frame
		_.cancel();

		// Unbind events
		emitter.off(events.effect.changed, _.handlers.effectChanged);
		emitter.off(events.store.changedDirty, _.handlers.storeDirty);
		emitter.off(events.store.optionsChanged, _.handlers.optionsInvalidated);
		emitter.off(events.store.slidesChanged, _.handlers.layoutInvalidated);
		emitter.off(events.window.resize, _.handlers.layoutInvalidated);

		// Destroy slide state manager
		if (_.#slideStateManager) {
			_.#slideStateManager.destroy();
			_.#slideStateManager = null;
		}

		// Clear references
		_.effect = null;
		_.#pipeline = null;
		_.ctx = null;
	}
}
