import { INTERACTIVE_SELECTOR } from './utils/utils.js';

/**
 * handles window and viewport events for the carousel
 */
export default class WindowEvents {
	/**
	 * creates a new window events instance
	 * @param {object} ctx - shared module context
	 * @param {object} ctx.emitter
	 * @param {object} ctx.events
	 * @param {HTMLElement} ctx.carousel
	 * @param {HTMLElement} ctx.viewport
	 */
	constructor(ctx) {
		const _ = this;

		// save ctx and frequently used refs
		_.ctx = ctx;
		_.carousel = ctx.carousel;
		_.viewport = ctx.viewport;

		// track viewport width to ignore height-only changes (mobile Safari bottom bar)
		_.lastViewportWidth = null;

		// per-element width cache for the unified observer (avoids height-only rebuilds)
		_.observedWidths = new WeakMap();
		// currently observed visibility-bounds element (when different from viewport)
		_.boundsElement = null;

		// define all event handlers in one object
		_.handlers = {
			// emit a canonical window:resize
			handleResize: (event) => {
				_.ctx.emitter.emit(_.ctx.events.window.resize, { event });
			},

			// focus carousel on click for keyboard navigation
			handleCarouselClick: (event) => {
				// only focus if clicking on the carousel itself or viewport/track,
				// not interactive elements. closest() reaching the carousel just
				// means nothing interactive sat between the target and the host
				// (the carousel matches via its own tabindex) — that still counts
				// as a non-interactive click.
				const interactive = event.target.closest(INTERACTIVE_SELECTOR);
				if (!interactive || interactive === _.carousel) {
					_.carousel.focus({ preventScroll: true });
				}
			},

			// window focus/blur
			handleWindowFocus: () => {
				_.ctx.emitter.emit(_.ctx.events.window.hasFocus, {});
			},
			handleWindowBlur: () => {
				_.ctx.emitter.emit(_.ctx.events.window.lostFocus, {});
			},

			// carousel focus/blur (component-level)
			handleCarouselFocus: (event) => {
				// notify plugins/features about focus entering the carousel
				_.ctx.emitter.emit(_.ctx.events.carousel.hasFocus, {});
				// the visibility rescue (SlideStateManager) moves focus
				// programmatically — that's the system, not the user
				if (_.carousel._tarotFocusRescue) return;
				// treat entering focus as user interaction (pause autoplay etc.)
				_.ctx.emitter.emit(_.ctx.events.user.interacted, { via: 'focus', event });
			},
			handleCarouselBlur: () => {
				_.ctx.emitter.emit(_.ctx.events.carousel.lostFocus, {});
			},

			// visibility change
			handleVisibilityChange: () => {
				_.ctx.emitter.emit(_.ctx.events.window.visibilityChange, { hidden: document.hidden });
			},

			// user inputs that imply interaction (for autoplay pause)
			handleKeyDown: (event) => {
				_.ctx.emitter.emit(_.ctx.events.user.interacted, { via: 'key', event });

				// core arrow key support only when carousel itself has focus
				// plugins handle their own keyboard events and call stopPropagation()
				if (['ArrowLeft', 'ArrowRight'].includes(event.key) && event.target === _.carousel) {
					event.preventDefault();
					const direction = event.key === 'ArrowLeft' ? -1 : 1;
					_.ctx.emitter.emit(_.ctx.events.keyboard.arrow, { direction, event });
				}
			},
			handleWheel: (event) => {
				// the wheel plugin stamps events it processed (and already emitted
				// user:interacted for); this fallback covers plugin-disabled carousels
				// and events the plugin ignored (e.g. over form fields)
				if (event.__tarotWheelHandled || event.__tarotWheelSeen) return;
				_.ctx.emitter.emit(_.ctx.events.user.interacted, { via: 'wheel', event });
			},

			// unified handler for resize and orientation change — runs per event
			// (no timer): window:resize consumers are cheap flag-sets or
			// self-debounced, and the layout work itself is frame-coalesced by
			// the FrameEngine's layoutDirty flag
			unifiedResizeHandler: (event) => {
				const currentWidth = _.viewport.clientWidth;
				// skip height-only changes (e.g., mobile Safari bottom bar show/hide)
				// only checked for window/orientation events; ResizeObserver already
				// did per-element early-out via _.observedWidths
				if (
					event !== undefined &&
					!(event instanceof ResizeObserverEntry) &&
					_.lastViewportWidth !== null &&
					currentWidth === _.lastViewportWidth
				) {
					return;
				}
				_.lastViewportWidth = currentWidth;
				_.handlers.handleResize(event);
			},

			// react to options changes by re-resolving the bounds element observation
			handleOptionsChanged: ({ currentOptions, previousOptions }) => {
				if (!currentOptions) return;
				if (
					previousOptions &&
					previousOptions.visibilityBoundsElement === currentOptions.visibilityBoundsElement
				) {
					return;
				}
				_.syncBoundsObservation();
			},
		};

		// unified resize observer: watches the viewport, and optionally the
		// visibility-bounds element when it differs from the viewport
		_.unifiedObserver = new ResizeObserver((entries) => {
			let changed = false;
			for (const entry of entries) {
				const w = entry?.contentRect?.width;
				if (w === undefined) continue;
				if (_.observedWidths.get(entry.target) === w) continue;
				_.observedWidths.set(entry.target, w);
				changed = true;
			}
			if (changed) _.handlers.unifiedResizeHandler(entries[0]);
		});

		_.init();
	}

	/**
	 * initializes viewport observer and calls bindEvents
	 */
	init() {
		const _ = this;

		// start observing the viewport for size changes
		if (_.viewport) {
			_.unifiedObserver.observe(_.viewport);
		}

		// initialize lastViewportWidth to current width
		_.lastViewportWidth = _.viewport.clientWidth;

		_.bindEvents();

		// resolve and start observing the visibility bounds element if needed
		_.syncBoundsObservation();
	}

	/**
	 * Resolves the current visibilityBoundsElement option and updates which
	 * element is being observed for resize. Called on init and on options changes.
	 */
	syncBoundsObservation() {
		const _ = this;
		const options = _.ctx.store.getOptions();
		const resolved = _.ctx.utils.resolveVisibilityBoundsElement(
			options.visibilityBoundsElement,
			_.carousel,
			_.viewport
		);

		// no change needed
		if (resolved === _.boundsElement) return;

		// stop observing the previous bounds element (if it wasn't the viewport)
		if (_.boundsElement && _.boundsElement !== _.viewport) {
			_.unifiedObserver.unobserve(_.boundsElement);
			_.observedWidths.delete(_.boundsElement);
		}

		_.boundsElement = resolved;

		// start observing the new bounds element (if it's distinct from viewport)
		if (resolved && resolved !== _.viewport) {
			_.unifiedObserver.observe(resolved);
		}

		// trigger a recompute so widths.visibilityBoundsWidth/Offset get updated
		_.handlers.unifiedResizeHandler();
	}

	/**
	 * binds all event listeners for window, document, and carousel
	 */
	// every DOM listener, listed once. bindEvents and destroy both walk this,
	// so a listener cannot be added without its matching teardown.
	#listeners() {
		const { carousel, handlers } = this;
		return [
			[window, 'resize', handlers.unifiedResizeHandler],
			[window, 'orientationchange', handlers.unifiedResizeHandler],
			[window, 'focus', handlers.handleWindowFocus],
			[window, 'blur', handlers.handleWindowBlur],
			[carousel, 'focus', handlers.handleCarouselFocus, true],
			[carousel, 'blur', handlers.handleCarouselBlur, true],
			[document, 'visibilitychange', handlers.handleVisibilityChange],
			[carousel, 'keydown', handlers.handleKeyDown, true],
			[carousel, 'wheel', handlers.handleWheel, { passive: true }],
			[carousel, 'click', handlers.handleCarouselClick, true],
		];
	}

	bindEvents() {
		const _ = this;
		for (const [target, type, handler, opts] of _.#listeners()) {
			target.addEventListener(type, handler, opts);
		}
		_.ctx.emitter.on(_.ctx.events.store.optionsChanged, _.handlers.handleOptionsChanged);
	}

	/**
	 * cleans up events and observers
	 */
	destroy() {
		const _ = this;

		for (const [target, type, handler, opts] of _.#listeners()) {
			target.removeEventListener(type, handler, opts);
		}
		_.ctx.emitter.off(_.ctx.events.store.optionsChanged, _.handlers.handleOptionsChanged);

		_.unifiedObserver.disconnect();
		_.unifiedObserver = null;

		_.boundsElement = null;
		_.observedWidths = null;
	}
}
